python3 - << 'PYEOF'
import json

with open('/tmp/ixp_receipt_registry.json') as f:
    ixp_d = json.load(f)
with open('/tmp/end_registry.json') as f:
    end_d = json.load(f)
with open('/tmp/script_registry.json') as f:
    script_d = json.load(f)

ixp_node = ixp_d['Data']['Node']
end_node = end_d['Data']['Node']
script_node = script_d['Data']['Node']

# Fix modelName null -> modelDisplayName per authoring rule #1
ixp_model_blob = dict(ixp_node['inputDefaults']['model'])
if not ixp_model_blob.get('modelName'):
    ixp_model_blob['modelName'] = ixp_model_blob['modelDisplayName']

flow = {
  "id": "c11bc5b7-a292-44dc-a497-c13d9aa11dcd",
  "version": "1.8",
  "name": "ReceiptExtraction",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": { "label": "Manual trigger" },
      "inputs": {
        "entryPointId": "b3c19815-f28e-439f-b01c-b21d49e10e57",
        "isDefaultEntryPoint": True
      }
    },
    {
      "id": "extractReceiptFields",
      "type": "uipath.ixp.idp-benchmark-receipts-43af6412-ixp.9e77f71d-773c-80a0-9411-ec40d252d00d-c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
      "typeVersion": "1.0.0",
      "display": { "label": "Extract Receipt Fields" },
      "inputs": {
        "model": ixp_model_blob,
        "modelName": ixp_node['inputDefaults']['modelName'],
        "description": "",
        "projectName": ixp_node['inputDefaults']['projectName'],
        "versionTag": "",
        "folderKey": ixp_node['inputDefaults']['folderKey'],
        "folderName": ixp_node['inputDefaults']['folderName'],
        "fileRef": "=js:$vars.start.output.receiptFile",
        "pageRange": ""
      },
      "outputs": {
        "output": ixp_node['outputDefinition']['output'],
        "error": ixp_node['outputDefinition']['error']
      }
    },
    {
      "id": "parseReceiptData",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": { "label": "Parse Merchant, Date, Total" },
      "inputs": {
        "language": "javascript",
        "code": """const fields = $vars.extractReceiptFields.output?.ExtractionResult?.ResultsDocument?.Fields || [];
const findField = (name) => fields.find(f => f.FieldName === name)?.Values?.[0] ?? null;
return {
  merchant: findField('vendor_name') ?? findField('merchant_name') ?? findField('store_name') ?? findField('VendorName') ?? null,
  date:     findField('purchase_date') ?? findField('date') ?? findField('Date') ?? null,
  total:    findField('total') ?? findField('Total') ?? findField('amount_due') ?? findField('AmountDue') ?? null
};"""
      },
      "outputs": {
        "output": {
          "type": "object",
          "var": "output"
        }
      }
    },
    {
      "id": "end",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": { "label": "End" },
      "inputs": {}
    }
  ],
  "edges": [
    {
      "id": "edge-start-to-extract",
      "sourceNodeId": "start",
      "targetNodeId": "extractReceiptFields",
      "sourceHandle": "output",
      "targetHandle": "input",
      "targetPort": "input"
    },
    {
      "id": "edge-extract-to-parse",
      "sourceNodeId": "extractReceiptFields",
      "targetNodeId": "parseReceiptData",
      "sourceHandle": "success",
      "targetHandle": "input",
      "targetPort": "input"
    },
    {
      "id": "edge-parse-to-end",
      "sourceNodeId": "parseReceiptData",
      "targetNodeId": "end",
      "sourceHandle": "success",
      "targetHandle": "input",
      "targetPort": "input"
    }
  ],
  "definitions": [
    # Manual trigger — already in file, keep verbatim from original
    {
      "nodeType": "core.trigger.manual",
      "version": "1.0",
      "category": "trigger",
      "description": "Start workflow manually",
      "tags": ["trigger", "start", "manual"],
      "sortOrder": 40,
      "display": { "label": "Manual trigger", "icon": "play", "shape": "circle" },
      "handleConfiguration": [
        {
          "position": "right",
          "handles": [
            { "id": "output", "type": "source", "handleType": "output", "showButton": True,
              "constraints": { "forbiddenTargetCategories": ["trigger"] } }
          ],
          "visible": True
        }
      ],
      "model": { "type": "bpmn:StartEvent", "entryPointId": True },
      "outputDefinition": {
        "output": { "type": "object", "description": "Data passed when manually triggering the workflow.", "source": "null", "var": "output" }
      },
      "toolbarExtensions": {
        "design": { "actions": [{ "id": "change-trigger-type", "icon": "square-mouse-pointer", "label": "Change trigger type" }] }
      }
    },
    # IxP definition — verbatim from registry get
    ixp_node,
    # Script definition — verbatim from registry get
    script_node,
    # End definition — verbatim from registry get
    end_node
  ],
  "layout": {
    "nodes": {
      "start": { "position": { "x": 256, "y": 144 } },
      "extractReceiptFields": { "position": { "x": 0, "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False },
      "parseReceiptData": { "position": { "x": 0, "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False },
      "end": { "position": { "x": 0, "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False }
    }
  }
}

with open('/tmp/receipt_flow_new.json', 'w') as f:
    json.dump(flow, f, indent=2)
print("written ok")
PYEOF
